// Kinetic: sticky results bar for the sport labs (generated by kinetic-tools/generators/labphone.py; do not hand-edit)
// Mirrors 1-2 result cards into .lab-bar (shown on phones, pinned under the header while you drag), announces them
// politely once a change is finished (not on every drag step), and gives each slider an aria-valuetext from its readout.
(function () {
  "use strict";
  var bar = document.querySelector(".lab .lab-bar");
  if (!bar) return;
  var lab = bar.closest(".lab");
  var items = [].slice.call(bar.querySelectorAll(".lbv[data-src]")).map(function (v) {
    var sh = []; try { sh = JSON.parse(v.getAttribute("data-short") || "[]").map(function (r) { return [new RegExp(r[0]), r[1]]; }); } catch (e) { sh = []; }
    return { v: v, sh: sh, src: document.getElementById(v.getAttribute("data-src")), k: v.parentNode.querySelector(".lbk").textContent };
  }).filter(function (it) { return it.src; });
  // the bar may show a compact form of the card text (e.g. "49 cm short") so it stays on one line; the card keeps the full text
  function compact(it, t) { for (var i = 0; i < it.sh.length; i++) if (it.sh[i][0].test(t)) return t.replace(it.sh[i][0], it.sh[i][1]); return t; }
  function sync() { items.forEach(function (it) { var t = compact(it, it.src.textContent); if (it.v.textContent !== t) it.v.textContent = t; }); }
  if (window.MutationObserver) {
    var mo = new MutationObserver(sync);
    items.forEach(function (it) { mo.observe(it.src, { childList: true, characterData: true, subtree: true }); });
  }
  lab.addEventListener("input", sync);
  sync();
  // pin the bar to the header's real bottom edge (the phone header is a little taller than --nav-h); CSS falls back to --nav-h
  var top = document.querySelector(".topbar");
  function pin() { var h = top && Math.round(top.getBoundingClientRect().height); if (h > 0) bar.style.setProperty("--lab-bar-top", h + "px"); }
  if (top) { pin(); window.addEventListener("resize", pin); if (window.ResizeObserver) new ResizeObserver(pin).observe(top); }
  // one polite announcement after a change settles (slider released, button pressed); nothing while dragging
  var live = document.createElement("div");
  live.className = "sr-only"; live.setAttribute("aria-live", "polite"); live.setAttribute("role", "status");
  lab.appendChild(live);
  var tm = 0;
  function announce() {
    clearTimeout(tm);
    tm = setTimeout(function () {
      sync();
      live.textContent = items.map(function (it) { return it.k + ": " + it.src.textContent; }).join(". ");   // full card wording
    }, 700);
  }
  lab.addEventListener("change", announce);
  lab.addEventListener("click", function (e) { if (e.target.closest && e.target.closest(".seg button")) announce(); });
  // sliders: read the visible value (e.g. "1000 m"), not the raw number
  [].slice.call(lab.querySelectorAll('.ctl input[type=range]')).forEach(function (r) {
    if (r.hasAttribute("aria-valuetext")) return;
    var o = r.parentNode.querySelector("output");
    if (!o) return;
    function vt() { var t = o.textContent.trim(); if (t) r.setAttribute("aria-valuetext", t); }
    r.addEventListener("input", vt); r.addEventListener("change", vt);
    if (window.MutationObserver) new MutationObserver(vt).observe(o, { childList: true, characterData: true, subtree: true });
    vt();
  });
})();
